function deploy(
        int256 _TARGET_UTILIZATION,
        int256 _INITIAL_RATE_AT_TARGET,
        int256 _MIN_RATE_AT_TARGET,
        int256 _MAX_RATE_AT_TARGET,
        int256 _CURVE_STEEPNESS,
        int256 _ADJUSTMENT_SPEED
    ) external returns (address) {
        // Deploy IRM.
        IRMAdaptiveCurve irm = new IRMAdaptiveCurve(
            _TARGET_UTILIZATION,
            _INITIAL_RATE_AT_TARGET,
            _MIN_RATE_AT_TARGET,
            _MAX_RATE_AT_TARGET,
            _CURVE_STEEPNESS,
            _ADJUSTMENT_SPEED
        );

        // Store the deployment and return the address.
        deploymentInfo[address(irm)] = DeploymentInfo(msg.sender, uint96(block.timestamp));
        deployments.push(address(irm));
        emit ContractDeployed(address(irm), msg.sender, block.timestamp);
        return address(irm);
    }

function claim(
        uint256 poolId
    ) external nonReentrant _checkPoolExists(poolId) {
        _updatePool(poolId);

        _claimRewards(poolId, msg.sender);
    }

function _updatePool(uint256 poolId) internal {
        Pool storage pool = pools[poolId];
        uint40 currentTime = uint40(block.timestamp);

        // Cache frequently accessed storage values
        uint40 rewardStartedAt = pool.rewardStartedAt;
        uint40 lastRewardUpdatedAt = pool.lastRewardUpdatedAt;

        // If rewards haven't started yet or no time passed, no need to update
        if (rewardStartedAt == 0 || currentTime <= lastRewardUpdatedAt) return;

        // Cache more values for efficiency
        uint32 rewardDuration = pool.rewardDuration;
        uint40 cancelledAt = pool.cancelledAt;
        uint256 endTime = rewardStartedAt + rewardDuration;

        // If pool is cancelled, use cancellation time as end time
        if (cancelledAt > 0 && cancelledAt < endTime) {
            endTime = cancelledAt;
        }
        uint256 toTime = currentTime > endTime ? endTime : currentTime;
        uint256 timePassed = toTime - lastRewardUpdatedAt;

        // Track allocated rewards if there are stakers and time has passed
        if (pool.totalStaked > 0 && timePassed > 0) {
            uint256 totalReward = Math.mulDiv(
                timePassed,
                pool.rewardAmount,
                pool.rewardDuration
            );
            // Track these rewards as allocated to users (earned, whether claimed or not)
            pool.totalAllocatedRewards += uint104(totalReward);
        }

        // Update accRewardPerShare
        pool.accRewardPerShare = _getUpdatedAccRewardPerShare(pool);

        pool.lastRewardUpdatedAt = uint40(toTime);
    }

function _claimRewards(uint256 poolId, address user) internal {
        Pool storage pool = pools[poolId];
        UserStake storage userStake = userPoolStake[user][poolId];

        // Use the helper function to calculate claimable rewards
        (uint256 claimAmount, uint256 fee) = _claimableReward(
            pool.accRewardPerShare,
            userStake.stakedAmount,
            userStake.rewardDebt
        );

        uint256 rewardAndFee = claimAmount + fee;
        assert(rewardAndFee <= pool.rewardAmount);
        if (rewardAndFee == 0) return;

        // Update user's reward debt and claimed rewards
        userStake.rewardDebt += rewardAndFee;
        // Safe to cast because claimAmount + fee <= pool.rewardAmount (uint104)
        userStake.claimedTotal += uint104(claimAmount);
        userStake.feeTotal += uint104(fee);

        // Transfer reward tokens to user (reward tokens are always ERC20)
        if (claimAmount > 0) {
            IERC20(pool.rewardToken).safeTransfer(user, claimAmount);
        }
        if (fee > 0) {
            IERC20(pool.rewardToken).safeTransfer(protocolBeneficiary, fee);
        }

        emit RewardClaimed(poolId, user, uint104(claimAmount), uint104(fee));
    }

function _getUpdatedAccRewardPerShare(
        Pool memory pool
    ) internal view returns (uint256 updatedAccRewardPerShare) {
        uint40 currentTime = uint40(block.timestamp);

        // If rewards haven't started yet or no staked, no rewards to distribute
        if (
            pool.rewardStartedAt == 0 ||
            pool.totalStaked == 0 ||
            currentTime <= pool.lastRewardUpdatedAt
        ) return pool.accRewardPerShare;

        uint256 endTime = pool.rewardStartedAt + pool.rewardDuration;
        // If pool is cancelled, use cancellation time as end time
        if (pool.cancelledAt > 0 && pool.cancelledAt < endTime)
            endTime = pool.cancelledAt;

        uint256 toTime = currentTime > endTime ? endTime : currentTime;
        uint256 timePassed = toTime - pool.lastRewardUpdatedAt;

        if (timePassed == 0) return pool.accRewardPerShare;

        uint256 totalReward = Math.mulDiv(
            timePassed,
            pool.rewardAmount,
            pool.rewardDuration
        );

        return
            pool.accRewardPerShare +
            Math.mulDiv(totalReward, REWARD_PRECISION, pool.totalStaked);
    }

function _claimableReward(
        uint256 updatedAccRewardPerShare,
        uint256 stakedAmount,
        uint256 originalRewardDebt
    ) internal view returns (uint256 rewardClaimable, uint256 fee) {
        if (stakedAmount == 0) return (0, 0);

        uint256 accRewardAmount = Math.mulDiv(
            stakedAmount,
            updatedAccRewardPerShare,
            REWARD_PRECISION
        );

        if (accRewardAmount <= originalRewardDebt) return (0, 0);

        rewardClaimable = accRewardAmount - originalRewardDebt;
        fee = Math.mulDiv(rewardClaimable, claimFee, 10000);
        rewardClaimable -= fee;
    }

function borrowDebt(BorrowParams calldata params, address _onBehalf) public payable nonReentrant whenNotPaused {
        // Delegated borrow (caller != owner) consumes the owner's credit-delegation allowance; self-borrow is free.
        if (_msgSender() != _onBehalf) {
            uint256 allowance = borrowDelegation[_onBehalf][_msgSender()];
            if (allowance < params.amount) revert InsufficientBorrowDelegation();
            borrowDelegation[_onBehalf][_msgSender()] = allowance - params.amount;
        }
        (uint256 creatorFee, uint256 protocolFee, uint256 userAmount, uint256 shares) = _borrowDebt(params.amount, _onBehalf);
        if (params.chainId == block.chainid) {
            // Same-chain borrow: deliver the funds to the caller.
            _borrowDebtTransfer(userAmount, creatorFee, protocolFee);
            emit BorrowDebt(_onBehalf, protocolFee, userAmount, shares, params.amount);
        } else {
            // Cross-chain borrow via Chainlink CCIP — guarded-off (reverts CrossChainDisabled) until the router
            // and destination selector are configured.
            _borrowDebtCrosschain(userAmount, creatorFee, protocolFee, params);
            emit BorrowDebtCrossChain(_onBehalf, protocolFee, userAmount, shares, params);
        }
    }

function _borrowDebt(uint256 _amount, address _user) internal returns (uint256, uint256, uint256, uint256) {
        return ILPRouter(router).borrowDebt(_amount, _user);
    }

function _borrowDebtTransfer(uint256 _userAmount, uint256 _creatorFee, uint256 _protocolFee) internal {
        address borrowToken = _borrowToken();
        if (borrowToken == address(1)) {
            _withdrawing = true;
            uint256 totalToWithdraw = _userAmount + _protocolFee + _creatorFee;
            IWrappedNative(_wrappedNative()).withdraw(totalToWithdraw);
            (bool sent,) = _protocol().call{ value: _protocolFee }("");
            if (!sent) revert TransferFailed(_protocolFee);
            (bool sent2,) = creator.call{ value: _creatorFee }("");
            if (!sent2) revert TransferFailed(_creatorFee);
            (bool sent3,) = _msgSender().call{ value: _userAmount }("");
            if (!sent3) revert TransferFailed(_userAmount);
            _withdrawing = false;
        } else {
            IERC20(borrowToken).safeTransfer(_protocol(), _protocolFee);
            IERC20(borrowToken).safeTransfer(creator, _creatorFee);
            IERC20(borrowToken).safeTransfer(_msgSender(), _userAmount);
        }
    }

function _borrowDebtCrosschain(uint256 _userAmount, uint256 _creatorFee, uint256 _protocolFee, BorrowParams memory params) internal {
        address ccipRouter = IFactory(_factory()).ccipRouter();
        uint64 destSelector = IFactory(_factory()).chainIdToSelector(params.chainId);
        if (ccipRouter == address(0) || destSelector == 0) revert CrossChainDisabled();

        // Native pools bridge the wrapped-native (WHSK) token; ERC-20 pools bridge the token itself.
        address token = _borrowToken() == address(1) ? _wrappedNative() : _borrowToken();

        // Protocol and creator fees stay on the source chain.
        IERC20(token).safeTransfer(_protocol(), _protocolFee);
        IERC20(token).safeTransfer(creator, _creatorFee);

        Client.EVMTokenAmount[] memory tokenAmounts = new Client.EVMTokenAmount[](1);
        tokenAmounts[0] = Client.EVMTokenAmount({ token: token, amount: _userAmount });

        Client.EVM2AnyMessage memory message = Client.EVM2AnyMessage({
            receiver: abi.encode(_msgSender()),
            data: "",
            tokenAmounts: tokenAmounts,
            feeToken: address(0), // pay the CCIP fee in native gas via msg.value
            extraArgs: Client._argsToBytes(Client.EVMExtraArgsV2({ gasLimit: uint256(params.destGasLimit), allowOutOfOrderExecution: true }))
        });

        IERC20(token).approve(ccipRouter, _userAmount);

        uint256 fee = IRouterClient(ccipRouter).getFee(destSelector, message);
        if (msg.value < fee) revert InsufficientFee(fee, msg.value);
        IRouterClient(ccipRouter).ccipSend{ value: fee }(destSelector, message);

        // Refund any native gas the caller over-sent beyond the quoted CCIP fee.
        uint256 refund = msg.value - fee;
        if (refund > 0) {
            (bool refunded,) = _msgSender().call{ value: refund }("");
            if (!refunded) revert TransferFailed(refund);
        }
    }

function _borrowToken() internal view returns (address) {
        return ILPRouter(router).borrowToken();
    }

function _wrappedNative() internal view returns (address) {
        return IFactory(_factory()).wrappedNative();
    }

function _protocol() internal view returns (address) {
        return IFactory(_factory()).protocol();
    }

function _factory() internal view returns (address) {
        return ILPRouter(router).factory();
    }

function addLiquidityETH(
    address token,
    uint256 amountTokenDesired,
    uint256 amountTokenMin,
    uint256 amountETHMin,
    address to,
    uint256 deadline
  )
    external
    payable
    virtual
    override
    ensure(deadline)
    returns (uint256 amountToken, uint256 amountETH, uint256 liquidity)
  {
    (amountToken, amountETH) = _addLiquidity(
      token,
      WETH,
      amountTokenDesired,
      msg.value,
      amountTokenMin,
      amountETHMin
    );
    address pair = HuskeyLibrary.pairFor(factory, token, WETH);
    TransferHelper.safeTransferFrom(token, msg.sender, pair, amountToken);
    IWETH(WETH).deposit{ value: amountETH }();
    assert(IWETH(WETH).transfer(pair, amountETH));
    liquidity = IHuskeyPair(pair).mint(to);
    // refund dust eth, if any
    if (msg.value > amountETH)
      TransferHelper.safeTransferETH(msg.sender, msg.value - amountETH);
  }

function _addLiquidity(
    address tokenA,
    address tokenB,
    uint256 amountADesired,
    uint256 amountBDesired,
    uint256 amountAMin,
    uint256 amountBMin
  ) internal virtual returns (uint256 amountA, uint256 amountB) {
    // create the pair if it doesn't exist yet
    if (IHuskeyFactory(factory).getPair(tokenA, tokenB) == address(0)) {
      IHuskeyFactory(factory).createPair(tokenA, tokenB);
    }
    (uint256 reserveA, uint256 reserveB) = HuskeyLibrary.getReserves(
      factory,
      tokenA,
      tokenB
    );
    if (reserveA == 0 && reserveB == 0) {
      (amountA, amountB) = (amountADesired, amountBDesired);
    } else {
      uint256 amountBOptimal = HuskeyLibrary.quote(amountADesired, reserveA, reserveB);
      if (amountBOptimal <= amountBDesired) {
        require(amountBOptimal >= amountBMin, 'HuskeyRouter: INSUFFICIENT_B_AMOUNT');
        (amountA, amountB) = (amountADesired, amountBOptimal);
      } else {
        uint256 amountAOptimal = HuskeyLibrary.quote(amountBDesired, reserveB, reserveA);
        assert(amountAOptimal <= amountADesired);
        require(amountAOptimal >= amountAMin, 'HuskeyRouter: INSUFFICIENT_A_AMOUNT');
        (amountA, amountB) = (amountAOptimal, amountBDesired);
      }
    }
  }

function pairFor(
    address factory,
    address tokenA,
    address tokenB
  ) internal pure returns (address pair) {
    (address token0, address token1) = sortTokens(tokenA, tokenB);
    pair = address(
      uint256(
        keccak256(
          abi.encodePacked(
            hex'ff',
            factory,
            keccak256(abi.encodePacked(token0, token1)),
            hex'31d4d4735f7b385a73bf8f4f40ce20074534e8112c1ff3324a1c032a2a17f021' // init code hash
          )
        )
      )
    );
  }

function safeTransferFrom(
    address token,
    address from,
    address to,
    uint256 value
  ) internal {
    // bytes4(keccak256(bytes('transferFrom(address,address,uint256)')));
    (bool success, bytes memory data) = token.call(
      abi.encodeWithSelector(0x23b872dd, from, to, value)
    );
    require(
      success && (data.length == 0 || abi.decode(data, (bool))),
      'TransferHelper: TRANSFER_FROM_FAILED'
    );
  }

function safeTransferETH(address to, uint256 value) internal {
    (bool success, ) = to.call{ value: value }(new bytes(0));
    require(success, 'TransferHelper: ETH_TRANSFER_FAILED');
  }

function getReserves(
    address factory,
    address tokenA,
    address tokenB
  ) internal view returns (uint256 reserveA, uint256 reserveB) {
    (address token0, ) = sortTokens(tokenA, tokenB);
    pairFor(factory, tokenA, tokenB);
    (uint256 reserve0, uint256 reserve1, ) = IHuskeyPair(pairFor(factory, tokenA, tokenB))
      .getReserves();
    (reserveA, reserveB) = tokenA == token0 ? (reserve0, reserve1) : (reserve1, reserve0);
  }

function quote(
    uint256 amountA,
    uint256 reserveA,
    uint256 reserveB
  ) internal pure returns (uint256 amountB) {
    require(amountA > 0, 'HuskeyLibrary: INSUFFICIENT_AMOUNT');
    require(reserveA > 0 && reserveB > 0, 'HuskeyLibrary: INSUFFICIENT_LIQUIDITY');
    amountB = amountA.mul(reserveB) / reserveA;
  }

function quote(
    uint256 amountA,
    uint256 reserveA,
    uint256 reserveB
  ) public pure virtual override returns (uint256 amountB) {
    return HuskeyLibrary.quote(amountA, reserveA, reserveB);
  }

function sortTokens(
    address tokenA,
    address tokenB
  ) internal pure returns (address token0, address token1) {
    require(tokenA != tokenB, 'HuskeyLibrary: IDENTICAL_ADDRESSES');
    (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
    require(token0 != address(0), 'HuskeyLibrary: ZERO_ADDRESS');
  }

function mul(uint256 x, uint256 y) internal pure returns (uint256 z) {
    require(y == 0 || (z = x * y) / y == x, 'ds-math-mul-overflow');
  }

function addLiquidityETH(
        address token,
        bool stable,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable ensure(deadline) returns (uint amountToken, uint amountETH, uint liquidity) {
        (amountToken, amountETH) = _addLiquidity(
            token,
            address(weth),
            stable,
            amountTokenDesired,
            msg.value,
            amountTokenMin,
            amountETHMin
        );
        address pair = pairFor(token, address(weth), stable);
        _safeTransferFrom(token, msg.sender, pair, amountToken);
        weth.deposit{value: amountETH}();
        assert(weth.transfer(pair, amountETH));
        liquidity = IPair(pair).mint(to);
        // refund dust eth, if any
        if (msg.value > amountETH) _safeTransferETH(msg.sender, msg.value - amountETH);
    }

function _addLiquidity(
        address tokenA,
        address tokenB,
        bool stable,
        uint amountADesired,
        uint amountBDesired,
        uint amountAMin,
        uint amountBMin
    ) internal returns (uint amountA, uint amountB) {
        require(amountADesired >= amountAMin);
        require(amountBDesired >= amountBMin);
        // create the pair if it doesn't exist yet
        address _pair = IPairFactory(factory).getPair(tokenA, tokenB, stable);
        if (_pair == address(0)) {
            _pair = IPairFactory(factory).createPair(tokenA, tokenB, stable);
        }
        (uint reserveA, uint reserveB) = getReserves(tokenA, tokenB, stable);
        if (reserveA == 0 && reserveB == 0) {
            (amountA, amountB) = (amountADesired, amountBDesired);
        } else {
            uint amountBOptimal = quoteLiquidity(amountADesired, reserveA, reserveB);
            if (amountBOptimal <= amountBDesired) {
                require(amountBOptimal >= amountBMin, 'Router: INSUFFICIENT_B_AMOUNT');
                (amountA, amountB) = (amountADesired, amountBOptimal);
            } else {
                uint amountAOptimal = quoteLiquidity(amountBDesired, reserveB, reserveA);
                assert(amountAOptimal <= amountADesired);
                require(amountAOptimal >= amountAMin, 'Router: INSUFFICIENT_A_AMOUNT');
                (amountA, amountB) = (amountAOptimal, amountBDesired);
            }
        }
    }

function pairFor(address tokenA, address tokenB, bool stable) public view returns (address pair) {
//        (address token0, address token1) = sortTokens(tokenA, tokenB);
//        pair = address(uint160(uint256(keccak256(abi.encodePacked(
//            hex'ff',
//            factory,
//            keccak256(abi.encodePacked(token0, token1, stable)),
//            pairCodeHash // init code hash
//        )))));
        pair = IPairFactory(factory).getPair(tokenA, tokenB, stable);
    }

function _safeTransferFrom(address token, address from, address to, uint256 value) internal {
        require(token.code.length > 0);
        (bool success, bytes memory data) =
        token.call(abi.encodeWithSelector(IERC20.transferFrom.selector, from, to, value));
        require(success && (data.length == 0 || abi.decode(data, (bool))));
    }

function _safeTransferETH(address to, uint value) internal {
        (bool success,) = to.call{value:value}(new bytes(0));
        require(success, 'TransferHelper: ETH_TRANSFER_FAILED');
    }

function getReserves(address tokenA, address tokenB, bool stable) public view returns (uint reserveA, uint reserveB) {
        (address token0,) = sortTokens(tokenA, tokenB);
        (uint reserve0, uint reserve1,) = IPair(pairFor(tokenA, tokenB, stable)).getReserves();
        (reserveA, reserveB) = tokenA == token0 ? (reserve0, reserve1) : (reserve1, reserve0);
    }

function quoteLiquidity(uint amountA, uint reserveA, uint reserveB) internal pure returns (uint amountB) {
        require(amountA > 0, 'Router: INSUFFICIENT_AMOUNT');
        require(reserveA > 0 && reserveB > 0, 'Router: INSUFFICIENT_LIQUIDITY');
        amountB = amountA * reserveB / reserveA;
    }

function sortTokens(address tokenA, address tokenB) public pure returns (address token0, address token1) {
        require(tokenA != tokenB, 'Router: IDENTICAL_ADDRESSES');
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(token0 != address(0), 'Router: ZERO_ADDRESS');
    }

function batchCancelListings(uint256[] calldata listingIds)
        external
        nonReentrant
        whenFunctionNotPaused
    {
        uint256 canceledCount = 0;
        for (uint256 i = 0; i < listingIds.length; i++) {
            AsteroidXMarketplaceStructs.Listing storage listing = listings[
                listingIds[i]
            ];
            if (listing.seller != msg.sender)
                revert NotSeller(listingIds[i], msg.sender);
            if (listing.active) {
                _deactivateListing(listingIds[i]);
                marketplaceVaultContract.returnNFTToSeller(
                    address(asteroidXToken),
                    listing.tokenId,
                    listing.amount,
                    listing.seller
                );
                _recordTransaction(
                    listing.tokenId,
                    AsteroidXMarketplaceStructs.ActivityType.CANCEL_LISTING,
                    msg.sender,
                    address(0),
                    listing.amount,
                    0,
                    listing.paymentToken,
                    listingIds[i]
                );
                emit ListingCancelled(listingIds[i]);
                canceledCount++;
            }
        }
        if (canceledCount > 0) {
            emit BatchOperation(
                uint256(
                    AsteroidXMarketplaceStructs.ActivityType.CANCEL_LISTING
                ),
                canceledCount
            );
        }
    }

function _deactivateListing(uint256 listingId) internal {
        AsteroidXMarketplaceStructs.Listing storage listing = listings[
            listingId
        ];
        if (!listing.active) return;
        listing.active = false;
        activeListingsByToken[listing.tokenId].remove(listingId);
        activeListingsBySeller[listing.seller].remove(listingId);
    }

function returnNFTToSeller(
        address tokenContract,
        uint256 tokenId,
        uint256 amount,
        address seller
    ) external onlyRole(MARKETPLACE_ROLE) whenNotPaused whenFunctionNotPaused {
        if (tokenContract == address(0)) revert InvalidTokenContract();
        if (seller == address(0)) revert InvalidRecipient();
        if (amount == 0) revert InvalidAmount();

        IERC1155(tokenContract).safeTransferFrom(
            address(this),
            seller,
            tokenId,
            amount,
            ""
        );
        emit NFTReturnedToSeller(tokenContract, tokenId, amount, seller);
    }

function _recordTransaction(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken,
        uint256 relatedId
    ) internal returns (uint256 priceHistoryIndex) {
        _recordActivity(
            tokenId,
            activityType,
            from,
            to,
            amount,
            price,
            paymentToken
        );
        if (
            activityType == AsteroidXMarketplaceStructs.ActivityType.SALE ||
            activityType ==
            AsteroidXMarketplaceStructs.ActivityType.ACCEPT_OFFER
        ) {
            priceHistoryIndex = _recordPriceHistory(
                relatedId,
                tokenId,
                price,
                amount,
                from,
                to,
                paymentToken
            );
        }
        return priceHistoryIndex;
    }

function remove(Bytes32Set storage set, bytes32 value) internal returns (bool) {
        return _remove(set._inner, value);
    }

function remove(AddressSet storage set, address value) internal returns (bool) {
        return _remove(set._inner, bytes32(uint256(uint160(value))));
    }

function remove(UintSet storage set, uint256 value) internal returns (bool) {
        return _remove(set._inner, bytes32(value));
    }

function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal {
        _callOptionalReturn(token, abi.encodeCall(token.transferFrom, (from, to, value)));
    }

function _recordActivity(
        uint256 tokenId,
        AsteroidXMarketplaceStructs.ActivityType activityType,
        address from,
        address to,
        uint256 amount,
        uint256 price,
        address paymentToken
    ) internal {
        tokenActivities[tokenId].push(
            AsteroidXMarketplaceStructs.Activity({
                activityType: activityType,
                from: from,
                to: to,
                tokenId: tokenId,
                amount: amount,
                price: price,
                timestamp: block.timestamp,
                paymentToken: paymentToken
            })
        );
    }

function _recordPriceHistory(
        uint256 relatedId,
        uint256 tokenId,
        uint256 pricePerToken,
        uint256 amount,
        address seller,
        address buyer,
        address paymentToken
    ) internal returns (uint256) {
        uint256 totalValue = pricePerToken * amount;
        AsteroidXMarketplaceStructs.PriceRecord
            memory priceRecord = AsteroidXMarketplaceStructs.PriceRecord({
                listingId: relatedId,
                tokenId: tokenId,
                price: pricePerToken,
                amount: amount,
                totalValue: totalValue,
                timestamp: block.timestamp,
                seller: seller,
                buyer: buyer,
                paymentToken: paymentToken
            });
        uint256 recordIndex = priceHistories.length;
        priceHistories.push(priceRecord);
        tokenPriceHistoryIndexes[tokenId].push(recordIndex);
        emit PriceHistoryRecorded(
            tokenId,
            relatedId,
            pricePerToken,
            amount,
            totalValue,
            block.timestamp,
            seller,
            buyer,
            paymentToken
        );
        return recordIndex;
    }

function _remove(Set storage set, bytes32 value) private returns (bool) {
        // We cache the value's position to prevent multiple reads from the same storage slot
        uint256 position = set._positions[value];

        if (position != 0) {
            // Equivalent to contains(set, value)
            // To delete an element from the _values array in O(1), we swap the element to delete with the last one in
            // the array, and then remove the last element (sometimes called as 'swap and pop').
            // This modifies the order of the array, as noted in {at}.

            uint256 valueIndex = position - 1;
            uint256 lastIndex = set._values.length - 1;

            if (valueIndex != lastIndex) {
                bytes32 lastValue = set._values[lastIndex];

                // Move the lastValue to the index where the value to delete is
                set._values[valueIndex] = lastValue;
                // Update the tracked position of the lastValue (that was just moved)
                set._positions[lastValue] = position;
            }

            // Delete the slot where the moved value was stored
            set._values.pop();

            // Delete the tracked position for the deleted slot
            delete set._positions[value];

            return true;
        } else {
            return false;
        }
    }

function _callOptionalReturn(IERC20 token, bytes memory data) private {
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            let success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            // bubble errors
            if iszero(success) {
                let ptr := mload(0x40)
                returndatacopy(ptr, 0, returndatasize())
                revert(ptr, returndatasize())
            }
            returnSize := returndatasize()
            returnValue := mload(0)
        }

        if (returnSize == 0 ? address(token).code.length == 0 : returnValue != 1) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

