        external
        onlyRole(Roles.ACTIVITY_SERVICE_ROLE)
        returns (address subAccount)
    {
        require(userWallet != address(0), "zero userWallet");

        address existing = _subAccountOf[userWallet];
        if (existing != address(0)) {
            return existing; // 幂等:已办卡则返回既有
