function lock(uint256 ruleId) public nonReentrant {
        require(!isPausingForOperation, "Contract is pausing for operation.");
        LockRule memory ruleInfo = lockRules[ruleId];
        require(ruleInfo.isValid, "Staking is invalid.");
        require(SUPPLY_LIMIT >= ruleInfo.rewardsAmount, "No more supply.");

        uint256 LOCK_AMOUNT = ruleInfo.lockAmount;
        uint256 fee = LOCK_AMOUNT * FEE_RATE / 10000;
        uint256 lockAmount = LOCK_AMOUNT - fee;
        bool feeSuccess = tokenATT.transferFrom(msg.sender, FEE_HOLDER, fee);
        require(feeSuccess, "Token transfer failed");
        bool lockSuccess = tokenATT.transferFrom(msg.sender, address(this), lockAmount);
        require(lockSuccess, "Token transfer failed");

        // Save user info
        userCurrentLockedId[msg.sender] += 1;
        userLockInfo[msg.sender][userCurrentLockedId[msg.sender]] = LockInfo(
            ruleId, msg.sender, userCurrentLockedId[msg.sender],
            lockAmount, block.timestamp, UNLOCK_DURATION,
            block.timestamp + UNLOCK_DURATION, ruleInfo.rewardsAmount, false
        );

        // Send rewards
        SUPPLY_LIMIT -= ruleInfo.rewardsAmount;
        require(SUPPLY_LIMIT >= ruleInfo.rewardsAmount, "Insufficient supply limit.");
        (bool rewardSuccess, ) = payable(msg.sender).call{value: ruleInfo.rewardsAmount}("");
        require(rewardSuccess, "Rewards failed");


        emit Lock(msg.sender, ruleId, lockAmount, block.timestamp);
    }

