function removeLiquidity(
        address tokenA,
        address tokenB,
        uint liquidity,
        uint amountAMin,
        uint amountBMin,
        address to,
        uint deadline
    ) public virtual override ensure(deadline) returns (uint amountA, uint amountB) {
        address pair = HyperindexV2Library.pairFor(factory, tokenA, tokenB);
        IHyperindexV2Pair(pair).transferFrom(msg.sender, pair, liquidity); // send liquidity to pair
        (uint amount0, uint amount1) = IHyperindexV2Pair(pair).burn(to);
        (address token0,) = HyperindexV2Library.sortTokens(tokenA, tokenB);
        (amountA, amountB) = tokenA == token0 ? (amount0, amount1) : (amount1, amount0);
        require(amountA >= amountAMin, 'HyperindexV2Router: INSUFFICIENT_A_AMOUNT');
        require(amountB >= amountBMin, 'HyperindexV2Router: INSUFFICIENT_B_AMOUNT');
    }

