function unlock(uint256 lockId) public nonReentrant {
        require(!isPausingForOperation, "Contract is pausing for operation.");
        LockInfo storage lockInfo = userLockInfo[msg.sender][lockId];
        uint256 unlockTime = lockInfo.unlockTime;
        require(block.timestamp >= unlockTime, "Unlock is not available yet. Please wait until the specified date.");

        uint256 unlockAmount = lockInfo.lockAmount;
        require(unlockAmount > 0, "No tokens available for unlock.");

        bool success = tokenATT.transfer(msg.sender, unlockAmount);
        require(success, "Withdraw failed");

        lockInfo.lockAmount = 0;
        lockInfo.isWithdrawn = true;

        emit Unlock(msg.sender, lockInfo.ruleId, unlockAmount, block.timestamp);
    }

function unstake(
        uint256 positionId
    ) external override nonReentrant validPosition(positionId) {
        Position[] storage positions = userPositions[msg.sender];
        Position storage position;
        uint256 posIndex;
        bool found = false;

        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].positionId == positionId) {
                position = positions[i];
                posIndex = i;
                found = true;
                break;
            }
        }

        if (!found) revert PositionNotFound();

        position = positions[posIndex];
        if (position.isUnstaked) revert AlreadyUnstaked();
        require(
            block.timestamp + TIME_TOLERANCE >= position.stakedAt + position.lockPeriod,
            "Still locked"
        );

        uint256 reward = _updateReward(msg.sender, posIndex);
        uint256 amount = position.amount;
        uint256 totalPayout = amount + reward;

        position.isUnstaked = true;
        userTotalStaked[msg.sender] -= amount;
        totalStaked -= amount;

        emit RewardClaimed(msg.sender, positionId, reward, block.timestamp);
        emit PositionUnstaked(msg.sender, positionId, amount, block.timestamp);

        (bool success, ) = msg.sender.call{value: totalPayout}("");
        require(success, "Transfer failed");
    }

function _updateReward(
        address _staker,
        uint256 _positionIndex
    ) internal returns (uint256 reward) {
        // Return 0 rewards if in emergency mode
        if (emergencyMode) return 0;

        Position storage position = userPositions[_staker][_positionIndex];
        if (position.isUnstaked) return 0;

        uint256 currentTime = block.timestamp;
        uint256 lockEndTime = position.stakedAt + position.lockPeriod;

        // Calculate time elapsed, capped at lock period
        uint256 timeElapsed;
        if (currentTime >= lockEndTime) {
            // If current time is beyond lock period, only calculate rewards up to lock end
            timeElapsed = lockEndTime - position.lastRewardAt;
            if (timeElapsed == 0) return 0;
        } else {
            // If still in lock period, calculate rewards normally
            timeElapsed = currentTime - position.lastRewardAt;
            if (timeElapsed == 0) return 0;
        }

        reward = StakingLib.calculateReward(
            position.amount, 
            timeElapsed, 
            position.rewardRate,
            position.lockPeriod   
        );

        // Update reward pool balance
        if (reward > 0) {
            require(rewardPoolBalance >= reward, "Insufficient reward pool");
            rewardPoolBalance -= reward;
            totalPendingRewards -= reward;
            emit RewardPoolUpdated(rewardPoolBalance);
        }

        position.lastRewardAt = currentTime > lockEndTime ? lockEndTime : currentTime;
    }

function calculateReward(
        uint256 amount,
        uint256 timeElapsed,
        uint256 rewardRate,
        uint256 lockPeriod
    ) public pure returns (uint256 reward) {
        // Early return for zero values
        if (amount == 0 || timeElapsed == 0 || rewardRate == 0) {
            return 0;
        }

        // If current time is beyond lock period, only calculate rewards up to lock end
        if (timeElapsed > lockPeriod) {
            timeElapsed = lockPeriod;
        }

        // High precision calculations using 18 decimals
        uint256 PRECISION = 1e18;

        // Input validation to prevent overflow
        require(amount <= type(uint256).max / PRECISION, "Amount too large");
        require(rewardRate <= BASIS_POINTS, "Rate too large");

        // Calculate annual rate with high precision
        uint256 annualRate = (rewardRate * PRECISION) / BASIS_POINTS;
        require(annualRate <= type(uint256).max / PRECISION, "Annual rate overflow");

        // Calculate complete years and remaining time
        uint256 completeYears = timeElapsed / SECONDS_PER_YEAR;
        uint256 remainingTime = timeElapsed % SECONDS_PER_YEAR;

        // Calculate rewards for complete years
        uint256 totalReward = calculateYearlyReward(amount, annualRate, PRECISION) * completeYears;

        // Calculate rewards for remaining time
        if (remainingTime > 0) {
            totalReward += calculateRemainingTimeReward(
                amount,
                annualRate,
                remainingTime,
                PRECISION
            );
        }

        // Validation check
        require(totalReward <= amount * rewardRate * (timeElapsed / SECONDS_PER_YEAR + 1) / BASIS_POINTS, 
            "Reward overflow");

        return totalReward;
    }

function calculateYearlyReward(
        uint256 amount,
        uint256 annualRate,
        uint256 PRECISION
    ) private pure returns (uint256) {
        return (amount * annualRate) / PRECISION;
    }

function calculateRemainingTimeReward(
        uint256 amount,
        uint256 annualRate,
        uint256 remainingTime,
        uint256 PRECISION
    ) private pure returns (uint256) {
        uint256 timeRatio = (remainingTime * PRECISION) / SECONDS_PER_YEAR;
        return (amount * annualRate * timeRatio) / (PRECISION * PRECISION);
    }

function unstakeLocked(uint256 _stakeId) external nonReentrant {
        require(_stakeId < lockedStakes[msg.sender].length, "Invalid stake ID");
        LockedStake storage lockedStake = lockedStakes[msg.sender][_stakeId];

        require(!lockedStake.withdrawn, "Stake already withdrawn");
        require(lockedStake.sharesAmount > 0, "Stake amount is zero");

        // Update reward pool
        updateRewardPool();

        // Check if early withdrawal
        bool isEarlyWithdrawal = (block.timestamp < lockedStake.lockEndTime);

        // Calculate penalty (if early withdrawal)
        uint256 penalty = 0;
        uint256 sharesToBurn = lockedStake.sharesAmount;
        uint256 hskToReturn = getHSKForShares(sharesToBurn);

        // 确定质押类型并更新该类型的质押总量
        StakeType stakeType;
        if (lockedStake.lockDuration == 30 days) stakeType = StakeType.FIXED_30_DAYS;
        else if (lockedStake.lockDuration == 90 days) stakeType = StakeType.FIXED_90_DAYS;
        else if (lockedStake.lockDuration == 180 days) stakeType = StakeType.FIXED_180_DAYS;
        else stakeType = StakeType.FIXED_365_DAYS;

        // 更新该锁定期类型的质押总量
        totalSharesByStakeType[stakeType] -= sharesToBurn;

        if (isEarlyWithdrawal) {
            // Calculate elapsed lock period ratio
            uint256 elapsedTime = block.timestamp - (lockedStake.lockEndTime - lockedStake.lockDuration);
            uint256 completionRatio = (elapsedTime * BASIS_POINTS) / lockedStake.lockDuration;

            // Adjust penalty based on completion (higher completion, lower penalty)
            uint256 adjustedPenalty = earlyWithdrawalPenalty[stakeType] * (BASIS_POINTS - completionRatio) / BASIS_POINTS;

            // Apply penalty
            penalty = (hskToReturn * adjustedPenalty) / BASIS_POINTS;
            hskToReturn -= penalty;

            // Add penalty to reserved rewards
            reservedRewards += penalty;
        }

        // Mark stake as withdrawn
        lockedStake.withdrawn = true;

        // Update total staked amount
        totalPooledHSK -= hskToReturn;

        // Check if user has enough stHSK
        require(stHSK.balanceOf(msg.sender) >= sharesToBurn, "Insufficient stHSK balance");

        // Burn stHSK tokens
        stHSK.burn(msg.sender, sharesToBurn);

        // Return HSK tokens
        bool transferSuccess = safeHskTransfer(payable(msg.sender), hskToReturn);
        require(transferSuccess, "HSK transfer failed");

        emit Unstake(msg.sender, sharesToBurn, hskToReturn, isEarlyWithdrawal, penalty, _stakeId);
    }

function updateRewardPool() public {
        if (block.number <= lastRewardBlock) {
            return;
        }

        if (totalPooledHSK == 0) {
            lastRewardBlock = block.number;
            return;
        }

        uint256 multiplier = block.number - lastRewardBlock;
        uint256 hskReward = multiplier * hskPerBlock;

        // Calculate and limit APR using configurable block time
        // SECONDS_PER_YEAR is 365 days (31,536,000 seconds)
        // Explicitly calculate blocks per year based on the configured block time
        uint256 blocksPerYear = SECONDS_PER_YEAR / blockTime;  // 31,536,000 / blockTime
        uint256 annualReward = hskPerBlock * blocksPerYear;
        uint256 currentAPR = (annualReward * BASIS_POINTS) / totalPooledHSK;
        if (currentAPR > MAX_APR) {
            hskReward = (totalPooledHSK * MAX_APR * multiplier) / (BASIS_POINTS * blocksPerYear);
        }

        // 计算额外的锁定期奖励
        uint256 additionalBonusRewards = 0;

        // 获取总shares数量
        uint256 totalShares = stHSK.totalSupply();

        if (totalShares > 0) {
            // 计算每种锁定期类型的额外奖励
            uint256 bonusReward30Days = 0;
            uint256 bonusReward90Days = 0;
            uint256 bonusReward180Days = 0;
            uint256 bonusReward365Days = 0;

            // 只有当该类型有质押时才计算奖励
            if (totalSharesByStakeType[StakeType.FIXED_30_DAYS] > 0) {
                // 计算该类型质押占总质押的比例
                uint256 shareRatio30Days = (totalSharesByStakeType[StakeType.FIXED_30_DAYS] * PRECISION_FACTOR) / totalShares;
                // 计算该类型的基础奖励
                uint256 baseReward30Days = (hskReward * shareRatio30Days) / PRECISION_FACTOR;
                // 计算该类型的额外奖励
                bonusReward30Days = (baseReward30Days * stakingBonus[StakeType.FIXED_30_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_90_DAYS] > 0) {
                uint256 shareRatio90Days = (totalSharesByStakeType[StakeType.FIXED_90_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward90Days = (hskReward * shareRatio90Days) / PRECISION_FACTOR;
                bonusReward90Days = (baseReward90Days * stakingBonus[StakeType.FIXED_90_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_180_DAYS] > 0) {
                uint256 shareRatio180Days = (totalSharesByStakeType[StakeType.FIXED_180_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward180Days = (hskReward * shareRatio180Days) / PRECISION_FACTOR;
                bonusReward180Days = (baseReward180Days * stakingBonus[StakeType.FIXED_180_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_365_DAYS] > 0) {
                uint256 shareRatio365Days = (totalSharesByStakeType[StakeType.FIXED_365_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward365Days = (hskReward * shareRatio365Days) / PRECISION_FACTOR;
                bonusReward365Days = (baseReward365Days * stakingBonus[StakeType.FIXED_365_DAYS]) / BASIS_POINTS;
            }

            // 计算总的额外奖励
            additionalBonusRewards = bonusReward30Days + bonusReward90Days + bonusReward180Days + bonusReward365Days;
        }

        // 总奖励 = 基础奖励 + 额外的锁定期奖励
        uint256 totalReward = hskReward + additionalBonusRewards;

        // Check if contract has enough HSK
        if (reservedRewards >= totalReward) {
            totalPooledHSK += totalReward;
            reservedRewards -= totalReward;

            // Update exchange rate
            emit ExchangeRateUpdated(totalPooledHSK, stHSK.totalSupply(), getHSKForShares(PRECISION_FACTOR));
        } else {
            if (reservedRewards > 0) {
                totalPooledHSK += reservedRewards;
                totalReward = reservedRewards;
                reservedRewards = 0;

                // Update exchange rate
                emit ExchangeRateUpdated(totalPooledHSK, stHSK.totalSupply(), getHSKForShares(PRECISION_FACTOR));
            }
            emit InsufficientRewards(totalReward, reservedRewards);
        }

        lastRewardBlock = block.number;
    }

function getHSKForShares(uint256 _sharesAmount) public view returns (uint256) {
        uint256 totalShares = stHSK.totalSupply();
        if (totalShares == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        return (_sharesAmount * totalPooledHSK) / totalShares;
    }

function balanceOf(address account) public view virtual returns (uint256) {
        return _balances[account];
    }

function burn(address from, uint256 sharesAmount) external onlyOwner {
        _burn(from, sharesAmount);
    }

function safeHskTransfer(address payable _to, uint256 _amount) internal returns (bool) {
        uint256 availableBalance = address(this).balance - totalPooledHSK;

        // 确保合约有足够的余额
        require(availableBalance >= _amount, "Insufficient contract balance");

        // 发送资金
        (bool success, ) = _to.call{value: _amount}("");
        require(success, "HSK transfer failed");
        return true;
    }

function totalSupply() public view virtual returns (uint256) {
        return _totalSupply;
    }

function _burn(address account, uint256 value) internal {
        if (account == address(0)) {
            revert ERC20InvalidSender(address(0));
        }
        _update(account, address(0), value);
    }

function _update(address from, address to, uint256 value) internal virtual {
        if (from == address(0)) {
            // Overflow check required: The rest of the code assumes that totalSupply never overflows
            _totalSupply += value;
        } else {
            uint256 fromBalance = _balances[from];
            if (fromBalance < value) {
                revert ERC20InsufficientBalance(from, fromBalance, value);
            }
            unchecked {
                // Overflow not possible: value <= fromBalance <= totalSupply.
                _balances[from] = fromBalance - value;
            }
        }

        if (to == address(0)) {
            unchecked {
                // Overflow not possible: value <= totalSupply or value <= fromBalance <= totalSupply.
                _totalSupply -= value;
            }
        } else {
            unchecked {
                // Overflow not possible: balance + value is at most totalSupply, which we know fits into a uint256.
                _balances[to] += value;
            }
        }

        emit Transfer(from, to, value);
    }

function withdrawCollateral(
        uint256 _amount,
        address _onBehalf
    )
        public
        whenNotPaused
        nonReentrant
        positionRequired(_onBehalf)
        nonZeroAmount(_amount)
        onlyOwnerOrWithdrawDelegate(_onBehalf)
    {
        _doWithdrawCollateral(_amount, _onBehalf);
    }

function _doWithdrawCollateral(uint256 _amount, address _owner) internal {
        _accrueInterest();
        _withdrawCollateralTransfer(_amount, _owner);
        emit WithdrawCollateral(_owner, _amount);
    }

function _accrueInterest() internal {
        ILPRouter(router).accrueInterest();
    }

function _withdrawCollateralTransfer(uint256 _amount, address _owner) internal {
        address position = _addressPositions(_owner);
        address tokenToCheck = _collateralToken() == address(1) ? _wrappedNative() : _collateralToken();
        uint256 userCollateralBalance = IERC20(tokenToCheck).balanceOf(position);
        if (_amount > userCollateralBalance) revert InsufficientCollateral(_amount, userCollateralBalance);
        IPosition(position).withdrawCollateral(_amount, _owner);
    }

function _addressPositions(address _user) internal view returns (address) {
        return ILPRouter(router).addressPositions(_user);
    }

function _collateralToken() internal view returns (address) {
        return ILPRouter(router).collateralToken();
    }

function _wrappedNative() internal view returns (address) {
        return IFactory(_factory()).wrappedNative();
    }

function _factory() internal view returns (address) {
        return ILPRouter(router).factory();
    }
